"""Root-owned native adapters and independent source/raw/full-route fixtures."""
import json
from pathlib import Path
HERE=Path(__file__).resolve().parent
COPY=Path(json.loads((HERE/'local-state.json').read_text())['scratch'])
TEST=COPY/'tests/contracts'
def write(name,text):
    path=TEST/name
    assert not path.exists()
    path.write_bytes(text.replace('\r\n','\n').replace('\n','\r\n').encode())
for name in ('PcbPassivePoseTrialSourceContractTest.java','PcbPassiveSizingSourceContractTest.java'):
    path=TEST/name;data=path.read_bytes()
    assert data.count(b'Rb56Plan.resolve(42L, 18)')+data.count(b'Rb56Plan.resolve(42L,18)')==1
    data=data.replace(b'Rb56Plan.resolve(42L, 18)',b'Rb56Plan.resolve(42L, 19)').replace(b'Rb56Plan.resolve(42L,18)',b'Rb56Plan.resolve(42L,19)')
    data=data.replace(b'interpretation18 rejects',b'interpretation19 rejects')
    path.write_bytes(data)
changes=[
(b'plan.placementInterpretationVersion != 17))',b'plan.placementInterpretationVersion != 17 &&\r\n                plan.placementInterpretationVersion != 18))'),
(b'Only explicit15/16/17 source intent is supported',b'Only explicit15/16/17/18 source intent is supported'),
(b'(version != 15 && version != 16 && version != 17) || plan == null',b'(version != 15 && version != 16 && version != 17 && version != 18) || plan == null'),
(b'(version == 15 ? 0 : version == 16 ? 1 : 2)',b'(version == 15 ? 0 : version == 16 ? 1 : version == 17 ? 2 : 3)'),
(b'Pose observation requires its exact bound15/16/17 source',b'Pose observation requires its exact bound15/16/17/18 source'),
(b'version == 15 ? "saved15" : version == 16 ? "pose16" : "size17", System.nanoTime()',b'version == 15 ? "saved15" : version == 16 ? "pose16" : version == 17 ? "size17" : "pose18", System.nanoTime()')]
path=TEST/'PcbPostSelectionEdgeTrimContractTest.java';data=path.read_bytes()
for before,after in changes:
    assert data.count(before)==1,before
    data=data.replace(before,after)
path.write_bytes(data)

write('PcbSourceSizedPoseSourceContractTest.java','package com.lushprojects.circuitjs1.client;\n/** Explicit native-only sizing-control source; no routed outcome assumptions. */\npublic final class PcbSourceSizedPoseSourceContractTest {\n    private static int assertions;\n    public static void main(String[] args) {\n        check(Rb56Placement.CURRENT_VERSION==15 && SeededPcbLayoutGenerator.CURRENT_VERSION==16,\n            "default epochs unchanged");\n        for(long seed:PcbPassivePoseTrialSourceContractTest.SEEDS)emit(seed);\n        boolean rejected=false;\n        try { Rb56Plan.resolve(42L,19); } catch(IllegalArgumentException expected) { rejected=true; }\n        check(rejected,"unsupported interpretation19 rejects");\n        System.out.println("PASS: PCB source sized pose source contracts roots=14 assertions="+assertions);\n    }\n    static Rb56Plan bound(long seed) {\n        PcbPassivePoseSourceContractTest.Expected expected=PcbPassivePoseSourceContractTest.expected(seed);\n        Rb56Plan saved=PcbPassivePoseSourceContractTest.boundPlan(expected);\n        Rb56Plan control=Rb56Plan.resolve(seed,18);\n        String canonical=saved.canonical(),epoch="placement-interpretation=15;";\n        check(canonical.indexOf(epoch)>=0 && canonical.indexOf(epoch)==canonical.lastIndexOf(epoch),\n            "one declared saved15 epoch");\n        check(control.canonical().equals(canonical.replace(epoch,"placement-interpretation=18;")),\n            "control source differs only by explicit interpretation");\n        TroubleshootBoard board=control.board();\n        PcbCanvasBoundaryContractTest.verifyBoardAgainstPlan(control,board);\n        check(PcbCanvasBoundaryContractTest.liveGraphSha256(board).equals(expected.graph),"literal graph unchanged");\n        check(PcbPostSelectionEdgeTrimContractTest.sourceIntentShaForPosePolicy(control).equals(expected.intent),\n            "literal source intent unchanged");\n        check(Long.toString(control.layoutSeed).equals(expected.layoutSeed) &&\n            Long.toString(control.routingSeed).equals(expected.routingSeed),"exact signed-long seeds unchanged");\n        check(board.getComponentIds().size()==expected.parts && board.getPadIds().size()==expected.pads,\n            "literal population unchanged");\n        PcbPlacementConstraints constraints=board.getPlacementConstraints();\n        check(constraints.placementDensityVersion==14 && constraints.passivePosePolicyVersion==3 &&\n            constraints.requiresTwoLayerRouting,"separate density14 policy3 with P07 routing");\n        check(constraints.getTraceWidthProfile()==PcbTraceWidthProfile.ROLE_WIDTHS &&\n            MediumBoardPhysicalPolicy.ID.equals(constraints.getPhysicalPolicyId()) &&\n            constraints.getPhysicalPolicyVersion()==MediumBoardPhysicalPolicy.VERSION,\n            "unchanged role widths and MEDIUM_BOARD physical policy");\n        check(MediumBoardNormalAdmission.rb56IdentityFor(constraints).equals("RB56_BOARD_NORMAL@4") &&\n            MediumBoardNormalAdmission.rb56IdentityForPlacement(18).equals("RB56_BOARD_NORMAL@4"),\n            "explicit trial identity4");\n        check(PcbPassivePoseTrialSourceContractTest.eligible(board).equals(\n            PcbPassivePoseTrialSourceContractTest.eligible(saved.board())),"passive inventory unchanged");\n        return control;\n    }\n    private static void emit(long seed) {\n        Rb56Plan saved=PcbPassivePoseTrialSourceContractTest.bound(seed,15),control=bound(seed);\n        TroubleshootBoard board=control.board();\n        StringBuilder json=new StringBuilder("{");\n        PcbPassivePoseTrialSourceContractTest.field(json,"seed",Long.toString(seed));\n        PcbPassivePoseTrialSourceContractTest.field(json,"sourceCanonical15",saved.canonical());\n        PcbPassivePoseTrialSourceContractTest.field(json,"sourcePlanSha25618",PcbCanvasBoundaryContractTest.sourcePlanSha256(control));\n        PcbPassivePoseTrialSourceContractTest.field(json,"graph18",PcbCanvasBoundaryContractTest.liveGraphSha256(board));\n        PcbPassivePoseTrialSourceContractTest.field(json,"intent18",PcbPostSelectionEdgeTrimContractTest.sourceIntentShaForPosePolicy(control));\n        PcbPassivePoseTrialSourceContractTest.field(json,"layoutSeed18",Long.toString(control.layoutSeed));\n        PcbPassivePoseTrialSourceContractTest.field(json,"routingSeed18",Long.toString(control.routingSeed));\n        json.append(",\\"eligibleIds\\":").append(PcbPassivePoseTrialSourceContractTest.array(\n            PcbPassivePoseTrialSourceContractTest.eligible(board)));\n        json.append(",\\"densityVersion18\\":").append(board.getPlacementConstraints().placementDensityVersion);\n        json.append(",\\"passivePosePolicy18\\":").append(board.getPlacementConstraints().passivePosePolicyVersion);\n        PcbPassivePoseTrialSourceContractTest.field(json,"admissionIdentity18",MediumBoardNormalAdmission.rb56IdentityFor(board.getPlacementConstraints()));\n        json.append(\'}\');\n        System.out.println("PCB_SOURCE_SIZED_POSE_INPUT "+json);\n    }\n    static void check(boolean value,String message) { assertions++;if(!value)throw new AssertionError(message); }\n}\n')
write('PcbSourceSizedPoseRawContractTest.java','package com.lushprojects.circuitjs1.client;\n/** Literal old raw baseline and control equality; no routing. */\npublic final class PcbSourceSizedPoseRawContractTest {\n    public static void main(String[] args) { run(42L,"PCB source sized pose raw42 contracts "); }\n    static void run(long seed,String marker) {\n        if(seed!=42L && seed!=-1022L && seed!=4L)throw new AssertionError("Fixed raw roots only");\n        Rb56Plan saved=PcbPassivePoseTrialSourceContractTest.bound(seed,15),control=PcbSourceSizedPoseSourceContractTest.bound(seed);\n        TroubleshootBoard oldBoard=saved.board(),newBoard=control.board();\n        String oldGraph=PcbCanvasBoundaryContractTest.liveGraphSha256(oldBoard);\n        String newGraph=PcbCanvasBoundaryContractTest.liveGraphSha256(newBoard);\n        PcbSourceSizedPoseSourceContractTest.check(oldGraph.equals(newGraph),"paired raw source graphs exact");\n        for(int attempt:new int[]{0,2,3,4,5}) {\n            PcbPlacementPlanner planner=new PcbPlacementPlanner(StandardPcbFootprintProviders.createRegistry());\n            PcbPlacementPlanner.Plan a=planner.plan(oldBoard,oldBoard.getPlacementConstraints(),saved.layoutSeed,attempt);\n            PcbPlacementPlanner.Plan b=planner.plan(newBoard,newBoard.getPlacementConstraints(),control.layoutSeed,attempt);\n            String first=PlayerSessionFingerprint.of(a.materialize().geometryFingerprint());\n            String second=PlayerSessionFingerprint.of(b.materialize().geometryFingerprint());\n            PcbSourceSizedPoseSourceContractTest.check(first.equals(second) && a.evaluations==b.evaluations &&\n                a.demandArea==b.demandArea && a.courtyardArea==b.courtyardArea && a.candidate==b.candidate,\n                "untouched candidate geometry/work/demand exact");\n            System.out.println("PCB_SOURCE_SIZED_POSE_RAW {\\"seed\\":\\""+seed+"\\",\\"attempt\\":"+attempt+\n                ",\\"geometry15\\":\\""+first+"\\",\\"geometry18\\":\\""+second+"\\",\\"evaluations15\\":"+a.evaluations+\n                ",\\"evaluations18\\":"+b.evaluations+",\\"demand15\\":"+a.demandArea+",\\"demand18\\":"+b.demandArea+\n                ",\\"courtyard15\\":"+a.courtyardArea+",\\"courtyard18\\":"+b.courtyardArea+"}");\n        }\n        PcbSourceSizedPoseSourceContractTest.check(oldGraph.equals(PcbCanvasBoundaryContractTest.liveGraphSha256(oldBoard)) &&\n            newGraph.equals(PcbCanvasBoundaryContractTest.liveGraphSha256(newBoard)),"raw generation leaves source graphs unchanged");\n        System.out.println("PASS: "+marker+"rows=5 routes=0");\n    }\n}\n')
